  "sutta_refs": "සූ. 357–360",
  "similar_words": "ද්වන්දො, ජයම්පතිකා, චක්ඛුසොතං, පාණිපාදං, හත්ථිගවස්සවළවං, අස්සත්ථකපිත්ථං, සාලියවං, හිරඤ්ඤසුවණ්ණං, කාසිකොසලං, හංසබකං ආදිය",
  "notes": [
   "ද්වන්ද්ව සමාසයෙන් සෑදුණු රූපය (පුබ්බාපර) පද සාධන ඛණ්ඩයේ නාම විභක්ති රීති අනුව වරනැඟේ; සමාස සාධනය ප්‍රකෘති සාධනයෙහි දක්වා ඇත."
  ],
