  "similar_words": "ද්වන්දො, ජයම්පතිකා, චක්ඛුසොතං, පුබ්බාපරං, පාණිපාදං, හත්ථිගවස්සවළවං, අස්සත්ථකපිත්ථං, සාලියවං, හිරඤ්ඤසුවණ්ණං, කාසිකොසලං ආදිය",
  "notes": [
   "ද්වන්ද්ව සමාසයෙන් සෑදුණු රූපය (හංසබක) පද සාධන ඛණ්ඩයේ නාම විභක්ති රීති අනුව වරනැඟේ; සමාස සාධනය ප්‍රකෘති සාධනයෙහි දක්වා ඇත."
  ],
